inputSpec:
[name: "image"
shortDescription: "Input image"
type {
  imageType {
    width: 640
    height: 640
    colorSpace: RGB
  }
}
, name: "iouThreshold"
shortDescription: "(optional) IoU threshold override (default: 0.5)"
type {
  doubleType {
  }
}
, name: "confidenceThreshold"
shortDescription: "(optional) Confidence threshold override (default: 0.1)"
type {
  doubleType {
  }
}
]

outputSpec:
[name: "confidence"
shortDescription: "Boxes × Class confidence (see user-defined metadata \"classes\")"
type {
  multiArrayType {
    dataType: FLOAT32
    shapeRange {
      sizeRanges {
        upperBound: -1
      }
      sizeRanges {
        lowerBound: 8
        upperBound: 8
      }
    }
  }
}
, name: "coordinates"
shortDescription: "Boxes × [x, y, width, height] (relative to image size)"
type {
  multiArrayType {
    dataType: FLOAT32
    shapeRange {
      sizeRanges {
        upperBound: -1
      }
      sizeRanges {
        lowerBound: 4
        upperBound: 4
      }
    }
  }
}
]
